259|static void lex_save_cached(lex_t *lex) {
260|    while (lex->stream.buffer[lex->stream.buffer_pos] != '\0') {
261|        lex_save(lex, lex->stream.buffer[lex->stream.buffer_pos]);
262|        lex->stream.buffer_pos++;
263|        lex->stream.position++;
264|    }
