578|        goto out;
579|    }
580|
581|    if (c == STREAM_STATE_ERROR) {
582|        lex->token = TOKEN_INVALID;
583|        goto out;
584|    }
585|
586|    lex_save(lex, c);
587|
588|    if (c == '{' || c == '}' || c == '[' || c == ']' || c == ':' || c == ',')
