46|  // Use the first sizeof(size_t) bytes as load flags.
47|  size_t load_flags = *(const size_t*)data;
48|  data += sizeof(size_t);
49|
50|  FUZZ_DEBUG("load_flags: 0x%zx\n"
51|             "& JSON_REJECT_DUPLICATES =  0x%zx\n"
52|             "& JSON_DECODE_ANY =         0x%zx\n"
53|             "& JSON_DISABLE_EOF_CHECK =  0x%zx\n"
54|             "& JSON_DECODE_INT_AS_REAL = 0x%zx\n"
55|             "& JSON_ALLOW_NUL =          0x%zx\n",
56|             load_flags,
57|             load_flags & JSON_REJECT_DUPLICATES,
58|             load_flags & JSON_DECODE_ANY,
59|             load_flags & JSON_DISABLE_EOF_CHECK,
60|             load_flags & JSON_DECODE_INT_AS_REAL,
61|             load_flags & JSON_ALLOW_NUL);
62|
63|  // Use the next sizeof(size_t) bytes as dump flags.
64|  size_t dump_flags = *(const size_t*)data;
65|  data += sizeof(size_t);
66|
67|  FUZZ_DEBUG("dump_flags: 0x%zx\n"
68|             "& JSON_MAX_INDENT =     0x%zx\n"
69|             "& JSON_COMPACT =        0x%zx\n"
70|             "& JSON_ENSURE_ASCII =   0x%zx\n"
71|             "& JSON_SORT_KEYS =      0x%zx\n"
72|             "& JSON_PRESERVE_ORDER = 0x%zx\n"
73|             "& JSON_ENCODE_ANY =     0x%zx\n"
74|             "& JSON_ESCAPE_SLASH =   0x%zx\n"
75|             "& JSON_REAL_PRECISION = 0x%zx\n"
76|             "& JSON_EMBED =          0x%zx\n",
77|             dump_flags,
78|             dump_flags & JSON_MAX_INDENT,
79|             dump_flags & JSON_COMPACT,
80|             dump_flags & JSON_ENSURE_ASCII,
81|             dump_flags & JSON_SORT_KEYS,
82|             dump_flags & JSON_PRESERVE_ORDER,
83|             dump_flags & JSON_ENCODE_ANY,
84|             dump_flags & JSON_ESCAPE_SLASH,
85|             ((dump_flags >> 11) & 0x1F) << 11,
86|             dump_flags & JSON_EMBED);
87|
88|  // Use the next byte as the dump mode.
89|  dump_mode = data[0];
90|  data++;
91|
92|  FUZZ_DEBUG("dump_mode: 0x%x", (unsigned int)dump_mode);
93|
94|  // Remove the command bytes from the size total.
95|  size -= NUM_COMMAND_BYTES;
96|
97|  // Attempt to load the remainder of the data with the given load flags.
98|  const char* text = reinterpret_cast<const char *>(data);
99|  json_t* jobj = json_loadb(text, size, load_flags, &error);
100|
101|  if (jobj == NULL)
102|  {
103|    return 0;
104|  }
105|
106|  if (dump_mode & FUZZ_DUMP_STRING)
107|  {
108|    // Dump as a string. Remove indents so that we don't run out of memory.
109|    char *out = json_dumps(jobj, dump_flags & ~JSON_MAX_INDENT);
110|    if (out != NULL)
111|    {
112|      free(out);
113|    }
114|  }
115|  else
116|  {
117|    // Default is callback mode.
118|    //
119|    // Attempt to dump the loaded json object with the given dump flags.
120|    uint64_t counter = 0;
121|
122|    json_dump_callback(jobj, json_dump_counter, &counter, dump_flags);
123|    FUZZ_DEBUG("Counter function counted %" PRIu64 " bytes.", counter);
124|  }
125|
126|  if (jobj)
127|  {
128|    json_decref(jobj);
129|  }
130|
131|  return 0;
