18|extern "C" int LLVMFuzzerTestOneInput(const uint8_t *data, size_t size)
19|{
20|    if (size < 2)
21|        return 0;
22|
23|    /* Use first byte to select format variant, rest as JSON input */
24|    uint8_t variant = data[0] % 8;
25|    const char *json_str = (const char *)(data + 1);
26|    size_t json_len = size - 1;
27|
28|    json_error_t error;
29|    json_t *root = json_loadb(json_str, json_len,
30|                               JSON_DECODE_ANY | JSON_ALLOW_NUL, &error);
31|    if (root == NULL)
32|        return 0;
33|
34|    /* Exercise json_deep_copy on whatever we parsed */
35|    json_t *copy = json_deep_copy(root);
36|    if (copy != NULL)
37|        json_decref(copy);
38|
39|    /* Exercise json_dumps with various flags */
40|    const int flag_sets[] = {
41|        0,
42|        JSON_COMPACT,
43|        JSON_ENSURE_ASCII,
44|        JSON_SORT_KEYS,
45|        JSON_COMPACT | JSON_ENSURE_ASCII,
46|    };
47|    int flags = flag_sets[variant % 5];
48|    char *dumped = json_dumps(root, flags);
49|    if (dumped != NULL) {
50|        /* Re-load the dumped output for round-trip check */
51|        json_t *reparsed = json_loads(dumped, 0, NULL);
52|        if (reparsed != NULL)
53|            json_decref(reparsed);
54|        free(dumped);
55|    }
56|
57|    /* Exercise json_unpack with simple format strings if root is an object */
58|    if (json_is_object(root)) {
59|        json_t *val = NULL;
60|        const char *key = NULL;
61|        /* Unpack first key-value pair */
62|        void *iter = json_object_iter(root);
63|        if (iter != NULL) {
64|            key = json_object_iter_key(iter);
65|            val  = json_object_iter_value(iter);
66|            (void)key;
67|            (void)val;
68|        }
69|
70|        /* json_unpack with "o" format — extract object */
71|        json_t *out_obj = NULL;
72|        json_unpack(root, "o", &out_obj);
73|
74|        /* json_unpack with "{s?o}" — optional key lookup */
75|        json_t *field = NULL;
76|        json_unpack(root, "{s?o}", "data", &field);
77|    }
78|
79|    /* Exercise json_unpack on array */
80|    if (json_is_array(root) && json_array_size(root) > 0) {
81|        json_t *first = NULL;
82|        json_unpack(root, "[o!]", &first);
83|    }
84|
85|    json_decref(root);
86|    return 0;
87|}

